def gen_ocean_island_questions(count=300):
    """海洋与岛屿专项题库"""
    qs = []
    q_id = [0]
    def Q_Q(q_text, choices, answer_idx, explanation=""):
        q_id[0] += 1
        qs.append({"id": f"{q_id[0]:04d}", "type": "choice",
                     "question": q_text, "options": choices,
                     "answer": choices[answer_idx], "answer_idx": answer_idx,
                     "explanation": explanation})
    def Q_J(q_text, correct, explanation=""):
        q_id[0] += 1
        qs.append({"id": f"{q_id[0]:04d}", "type": "judge",
                     "question": q_text, "answer": "V" if correct else "X",
                     "is_correct": correct, "explanation": explanation})
