def gen_bio_chapter_questions(chapter_id, topics, count=200):
    """为生物章节生成200+道题"""
    questions = []
    q_id = 1
    
    # 生物第一章：认识生物
    if '7_1_1' in chapter_id:
        base_qs = _get_bio_7_1_1_full()
    # 生物第二章：认识细胞
    elif '7_1_2' in chapter_id:
        base_qs = _get_bio_7_1_2_full()
    # 生物第三章：从细胞到生物体
    elif '7_1_3' in chapter_id:
        base_qs = _get_bio_7_1_3_full()
    # 植物类群
    elif '7_2_1' in chapter_id:
        base_qs = _get_bio_plants_full()
    # 动物类群
    elif '7_2_2' in chapter_id:
        base_qs = _get_bio_animals_full()
    # 微生物
    elif '7_2_3' in chapter_id:
        base_qs = _get_bio_microbes_full()
    # 被子植物
    elif '7_3_1' in chapter_id:
        base_qs = _get_bio_flowering_full()
    # 光合作用
    elif '7_3_2' in chapter_id:
        base_qs = _get_bio_photosynthesis_full()
    # 人的由来
    elif '7_4_1' in chapter_id:
        base_qs = _get_bio_human_full()
    # 人体营养
    elif '7_4_2' in chapter_id:
        base_qs = _get_bio_nutrition_full()
    # 人体呼吸
    elif '7_4_3' in chapter_id:
        base_qs = _get_bio_respiration_full()
    # 物质运输
    elif '7_4_4' in chapter_id:
        base_qs = _get_bio_transport_full()
    # 排泄
    elif '7_4_5' in chapter_id:
        base_qs = _get_bio_excretion_full()
    # 动物运动
    elif '8_1_1' in chapter_id:
        base_qs = _get_bio_movement_full()
    # 动物行为
    elif '8_1_2' in chapter_id:
        base_qs = _get_bio_behavior_full()
    # 微生物作用
    elif '8_2_1' in chapter_id:
        base_qs = _get_bio_microbe_role_full()
    # 细菌真菌
    elif '8_3_1' in chapter_id:
        base_qs = _get_bio_bacteria_fungi_full()
    # 细菌真菌利用
    elif '8_3_2' in chapter_id:
        base_qs = _get_bio_bacteria_fungi_use_full()
    # 植物生殖
    elif '8_4_1' in chapter_id:
        base_qs = _get_bio_reproduction_full()
    # 遗传变异
    elif '8_5_1' in chapter_id:
        base_qs = _get_bio_heredity_full()
    # 生物进化
    elif '8_5_2' in chapter_id:
        base_qs = _get_bio_evolution_full()
    # 传染病免疫
    elif '8_6_1' in chapter_id:
        base_qs = _get_bio_immunity_full()
    # 用药急救
    elif '8_6_2' in chapter_id:
        base_qs = _get_bio_firstaid_full()
    # 健康
    elif '8_7_1' in chapter_id:
        base_qs = _get_bio_health_full()
    elif '7_2_4' in chapter_id:
        base_qs = _get_bio_7_2_4_full()
    elif '7_3_3' in chapter_id:
        base_qs = _get_bio_7_3_3_full()
    elif '8_4_2' in chapter_id:
        base_qs = _get_bio_8_4_2_full()
    elif '8_4_3' in chapter_id:
        base_qs = _get_bio_8_4_3_full()
    else:
        base_qs = _get_generic_bio_full()
    
    # 生成题目，去重后取够 count 道
    seen = set()
    for item in base_qs:
        t = item['question'].strip()
        if t not in seen:
            seen.add(t)
            q = item.copy()
            q['id'] = f'{chapter_id}_{q_id}'
            q['topic'] = topics[q_id % len(topics)] if topics else '基础知识'
            questions.append(q)
            q_id += 1
            if len(questions) >= count:
                break
    # 若池子不够，重新打乱后第二轮去重补足
    if len(questions) < count:
        extra = []
        extra_seen = set(q['question'].strip() for q in questions)
        import random
        pool = list(base_qs)
        random.shuffle(pool)
        for item in pool:
            t = item['question'].strip()
            if t not in extra_seen:
                extra_seen.add(t)
                q = item.copy()
                q['id'] = f'{chapter_id}_{q_id}'
                q['topic'] = topics[q_id % len(topics)] if topics else '基础知识'
                extra.append(q)
                q_id += 1
                if len(extra) + len(questions) >= count:
                    break
        questions.extend(extra[:count - len(questions)])
    
    return questions

def gen_geo_chapter_questions(chapter_id, topics, count=200):
    """为地理章节生成200+道题"""
    questions = []
    q_id = 1
    
    # 地球和地图 (geo_7_1_1)
