def _get_geo_continents_full():
    """认识大洲 - 200道高质量题目"""
    qs = []
    q_id = [0]
    
    def Q(question, options, answer_idx, explanation="", topic=""):
        q_id[0] += 1
        qs.append({
            'id': f'geo_7_2_1_{q_id[0]:04d}',
            'type': 'choice',
            'question': question,
            'options': options,
            'answer': options[answer_idx],
            'answer_idx': answer_idx,
            'explanation': explanation,
            'topic': topic
        })
    
    # 非洲 (50题)
    Q('非洲大陆的地形以什么为主？', ['平原', '高原', '山地', '盆地'], 1, '非洲有"高原大陆"之称，平均海拔750米。', '非洲地形')
    Q('非洲最高峰乞力马扎罗山位于哪个国家？', ['肯尼亚', '坦桑尼亚', '乌干达', '埃塞俄比亚'], 1, '乞力马扎罗山位于坦桑尼亚，海拔5895米。', '非洲地形')
    Q('世界最大的沙漠撒哈拉沙漠位于非洲的哪个部位？', ['东部', '西部', '北部', '南部'], 2, '撒哈拉沙漠位于非洲北部，面积约906万平方公里。', '非洲气候')
    Q('非洲气候分布的特点是？', ['以热带气候为主，呈南北对称分布', '以温带气候为主', '以寒带气候为主', '气候类型单一'], 0, '非洲3/4面积位于热带，气候以赤道为轴呈南北对称分布。', '非洲气候')
    Q('非洲流量最大的河流是？', ['尼日尔河', '刚果河', '赞比西河', '尼罗河'], 1, '刚果河流量仅次于亚马孙河，居世界第二。', '非洲河流')
    Q('世界上最长的河流是？', ['亚马孙河', '长江', '尼罗河', '密西西比河'], 2, '尼罗河全长约6650公里，是世界第一长河。', '非洲河流')
    Q('非洲最大的湖泊是？', ['坦噶尼喀湖', '马拉维湖', '乍得湖', '维多利亚湖'], 3, '维多利亚湖面积约6.9万平方公里，是非洲最大湖泊。', '非洲湖泊')
    Q('东非大裂谷的形成原因是？', ['板块碰撞挤压', '板块张裂拉伸', '火山喷发', '冰川侵蚀'], 1, '东非大裂谷是非洲板块与印度洋板块张裂拉伸形成的。', '非洲地形')
    Q('非洲最大的岛屿是？', ['马达加斯加岛', '毛里求斯岛', '塞舌尔群岛', '科摩罗群岛'], 0, '马达加斯加岛面积约58.7万平方公里，是世界第四大岛。', '非洲地理')
    Q('非洲人口最多的国家是？', ['埃及', '埃塞俄比亚', '尼日利亚', '刚果(金)'], 2, '尼日利亚人口约2.2亿，是非洲第一人口大国。', '非洲人口')
    Q('非洲经济最发达的国家是？', ['埃及', '南非', '尼日利亚', '肯尼亚'], 1, '南非是非洲工业化程度最高的国家。', '非洲经济')
