        qs.append({
            'id': f'geo_7_2_2_{q_id[0]:04d}',
            'type': 'choice',
            'question': question,
            'options': options,
            'answer': options[answer_idx],
            'answer_idx': answer_idx,
            'explanation': explanation,
            'topic': topic
        })
    
