def _get_geo_countries_full():
    """认识国家 - 200道高质量题目"""
    qs = []
    q_id = [0]
    
    def Q(question, options, answer_idx, explanation="", topic=""):
        q_id[0] += 1
        qs.append({
            'id': f'geo_7_2_3_{q_id[0]:04d}',
            'type': 'choice',
            'question': question,
            'options': options,
            'answer': options[answer_idx],
            'answer_idx': answer_idx,
            'explanation': explanation,
            'topic': topic
        })
    
    # 日本 (40题)
    Q('日本位于亚洲的哪个部位？', ['东北部', '东部', '东南部', '西北部'], 1, '日本位于亚洲东部，太平洋西北部。', '日本位置')
    Q('日本领土主要由哪四个大岛组成？', ['北海道、本州、四国、九州', '本州、四国、九州、冲绳', '北海道、本州、九州、琉球', '本州、四国、九州、四国'], 0, '日本由北海道、本州、四国、九州四大岛组成。', '日本领土')
    Q('日本最大的岛屿是？', ['北海道', '本州', '四国', '九州'], 1, '本州岛面积约22.7万平方公里，是日本最大岛屿。', '日本领土')
