# ==================== 通用题库生成模板 ====================

def _gen_bio_topic_qs(topic_str, count):
    """生成生物题库 - 按topic智能匹配内容（修复：不再混入无关章节）"""
    import random
    topics = topic_str.replace(' ', '').split('、')
    topic_text = topic_str  # 原始topic字符串用于匹配
    pool = []

    # ====== 智能分类：根据topic决定添加哪些专项题 ======
    # 注意：植物类群/动物类群是分类章节，不应触发生理专项
    is_classification = any(kw in topic_text for kw in ['类群', '分类', '多样性'])
