        # 移除低质量通用模板题，保持专项题库质量
    # 专项题库（光合/呼吸/叶绿体/线粒体/碳循环）已足够支撑各章节
    bio_skip = {'光合作用', '呼吸作用', '叶绿体', '线粒体'}

    # 兜底：如果pool为空（分类章节），添加基础生物知识题
    if len(pool) == 0:
        pool.append({'difficulty': 'medium', 'type': 'select', 'question': '生物分类的基本单位是',
                     'options': ['种', '属', '科', '界'], 'answer': '种', 'explanation': '种是生物分类的基本单位'})
        pool.append({'difficulty': 'medium', 'type': 'select', 'question': '生物分类的主要依据是',
                     'options': ['形态结构和生理功能', '颜色和大小', '生长地点', '发现时间'], 'answer': '形态结构和生理功能', 'explanation': '生物分类依据形态结构、生理功能等特征'})
        pool.append({'difficulty': 'medium', 'type': 'judge', 'question': '生物分类可以帮助我们了解生物之间的亲缘关系', 'answer': True, 'explanation': '分类系统反映生物的进化关系'})
        pool.append({'difficulty': 'easy', 'type': 'judge', 'question': '同种生物之间的差异最大', 'answer': False, 'explanation': '同种生物亲缘关系最近，差异最小'})
        pool.append({'difficulty': 'medium', 'type': 'fill', 'question': '生物分类的等级从大到小依次是界、门、纲、目、科、属、____', 'answer': ['种'], 'explanation': '界门纲目科属种是分类的七个等级'})

    # 采样
    if len(pool) >= count:
        sampled = random.sample(pool, count)
    else:
        result = list(pool)
        seen = {q['question'] for q in pool}
        while len(result) < count:
            random.shuffle(pool)
            for q in pool:
                if q['question'] not in seen:
                    seen.add(q['question'])
                    result.append(q.copy())
                    if len(result) >= count:
                        break
            if len(result) >= count:
                break
            # 已耗尽不重复文本，强制循环填充
            while len(result) < count:
                random.shuffle(pool)
                for q in pool:
                    result.append(q.copy())
                    if len(result) >= count:
                        break
        sampled = result[:count]

    return sampled

